/// The declared topic whose pattern matches the concrete `topic`.
#[rustfmt::skip]
pub fn declared_topic(topic: &str) -> Option<&'static topics::TopicDecl> {
    DECLARED_TOPICS.iter().find(|decl| topics::matches(decl.name, topic))
}
